1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export interface QuoteStep {
11	  op: "quote";
12	  items: Item[];
13	}
14	
15	export interface Item {
16	  type: string;
17	  material?: string;
18	  enchantment?: number;
19	  cursed?: boolean;
20	}
21	
22	export type Step = QuoteStep;
23	
24	export interface QuoteResult {
25	  premium: number;
26	}
27	
28	export type StepResult = QuoteResult;
29	
30	export interface ScenarioResult {
31	  results: StepResult[];
32	}
33	
34	const sumBy = <T>(values: T[], amount: (value: T) => number): number =>
35	  values.reduce((total, value) => total + amount(value), 0);
36	
37	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
38	  sword: 100,
39	  amulet: 60,
40	  staff: 80,
41	  potion: 40,
42	  rune: 25,
43	  moonstone: 25,
44	};
45	
46	const itemBasePremium = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
47	
48	const BLOCK_SIZE = 3;
49	
50	const BLOCK_BASE_PREMIUM = 60;
51	
52	const basePremiumForSameTypeItems = (items: Item[]): number =>
53	  items.length === BLOCK_SIZE
54	    ? BLOCK_BASE_PREMIUM
55	    : sumBy(items, itemBasePremium);
56	
57	const sameTypeGroups = (items: Item[]): Item[][] => {
58	  const groupsByType = new Map<string, Item[]>();
59	  for (const item of items) {
60	    const group = groupsByType.get(item.type) ?? [];
61	    group.push(item);
62	    groupsByType.set(item.type, group);
63	  }
64	  return [...groupsByType.values()];
65	};
66	
67	const CURSE_SURCHARGE_RATE = 0.5;
68	
69	const HIGH_ENCHANTMENT_LEVEL = 5;
70	
71	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
72	
73	interface SurchargeRule {
74	  appliesTo: (item: Item) => boolean;
75	  rate: number;
76	}
77	
78	const SURCHARGE_RULES: SurchargeRule[] = [
79	  {
80	    appliesTo: (item) => item.cursed === true,
81	    rate: CURSE_SURCHARGE_RATE,
82	  },
83	  {
84	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL,
85	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
86	  },
87	];
88	
89	const itemSurchargeRate = (item: Item): number =>
90	  sumBy(
91	    SURCHARGE_RULES.filter((rule) => rule.appliesTo(item)),
92	    (rule) => rule.rate,
93	  );
94	
95	const itemSurcharge = (item: Item): number =>
96	  itemBasePremium(item) * itemSurchargeRate(item);
97	
98	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
99	
100	const PROCESSING_FEE = 5;
101	
102	const LOYALTY_YEARS = 2;
103	
104	const LOYALTY_DISCOUNT_RATE = 0.2;
105	
106	const loyaltyDiscountRate = (customer: Customer): number =>
107	  customer.yearsWithMHPCO >= LOYALTY_YEARS ? -LOYALTY_DISCOUNT_RATE : 0;
108	
109	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = 0.15;
110	
111	const followUpContractDiscountRate = (precedingContracts: number): number =>
112	  precedingContracts > 0 ? -FOLLOW_UP_CONTRACT_DISCOUNT_RATE : 0;
113	
114	// Policy-wide modifiers are rates applied to the policy base premium.
115	// Surcharges are positive rates, discounts negative ones.
116	const policyModifierRate = (
117	  customer: Customer,
118	  precedingContracts: number,
119	): number =>
120	  FIRST_INSURANCE_SURCHARGE_RATE +
121	  loyaltyDiscountRate(customer) +
122	  followUpContractDiscountRate(precedingContracts);
123	
124	const quotePremium = (
125	  step: QuoteStep,
126	  customer: Customer,
127	  precedingContracts: number,
128	): number => {
129	  const policyBasePremium = sumBy(
130	    sameTypeGroups(step.items),
131	    basePremiumForSameTypeItems,
132	  );
133	  const itemSurcharges = sumBy(step.items, itemSurcharge);
134	  const policyModifiers =
135	    policyBasePremium * policyModifierRate(customer, precedingContracts);
136	  // Rounded in the MHPCO's favour; only the final premium is rounded.
137	  return Math.ceil(
138	    policyBasePremium + itemSurcharges + policyModifiers + PROCESSING_FEE,
139	  );
140	};
141	
142	export const runScenario = (scenario: Scenario): ScenarioResult => {
143	  const results: StepResult[] = [];
144	  let concludedContracts = 0;
145	  for (const step of scenario.steps) {
146	    results.push({
147	      premium: quotePremium(step, scenario.customer, concludedContracts),
148	    });
149	    concludedContracts += 1;
150	  }
151	  return { results };
152	};
