// Exhaustive check: for every policy base premium reachable from the item
// catalogue, does `base * (1 + rate)` differ from `base + base * rate`?
const rates = [];
for (const first of [0.1])
  for (const loyalty of [0, -0.2])
    for (const follow of [0, -0.15])
      rates.push(first + loyalty + follow);

// Reachable bases: sums of {100,60,80,40,25} and block value 60, up to 8 items.
const units = [100, 60, 80, 40, 25, 60];
const bases = new Set([0]);
for (let i = 0; i < 8; i++)
  for (const b of [...bases]) for (const u of units) bases.add(b + u);

let split = 0, factored = 0, disagree = 0;
for (const base of bases) {
  for (const rate of rates) {
    const a = base + base * rate;          // current
    const b = base * (1 + rate);           // proposed
    if (a !== b) {
      disagree++;
      if (disagree <= 6) console.log(`base=${base} rate=${rate} split=${a} factored=${b}`);
    }
  }
}
console.log(`bases=${bases.size} rates=${rates.length} disagreements=${disagree}`);
EOF
